<template>
  <section class="admin-page tasks-page">
    <PageHeader title="任务监控"><template #actions><t-button variant="outline" :loading="refreshing" :disabled="refreshing" @click="loadTasks(true)"><template #icon><i-refresh theme="outline" /></template>刷新</t-button></template></PageHeader>
    <div class="toolbar"><label><span>状态</span><t-select v-model="filters.state" :options="stateOptions" @change="applyFilters" /></label><label><span>任务类型</span><t-select v-model="filters.taskClass" :options="taskClassOptions" @change="applyFilters" /></label><label v-if="isSuperAdmin"><span>分组</span><t-select v-model="filters.groupId" :options="groupOptions" @change="applyFilters" /></label><label><span>负责人</span><t-select v-model="filters.ownerUserId" :options="userOptions" @change="applyFilters" /></label></div>
    <LoadingState v-if="loading" text="正在加载任务..." /><ErrorState v-else-if="loadError" :message="loadError" retryable @retry="loadTasks()" />
    <section v-else class="data-section" aria-labelledby="tasks-title"><div class="section-heading"><h2 id="tasks-title">任务列表</h2><span>共 {{ result.total }} 个</span></div><EmptyState v-if="result.items.length === 0" text="暂无符合条件的任务" /><div v-else class="table-scroll"><table><thead><tr><th>任务</th><th>项目</th><th>负责人</th><th>分组</th><th>类型 / 模型</th><th>状态</th><th>开始时间</th><th>结果说明</th></tr></thead><tbody>
      <tr v-for="task in result.items" :key="task.id"><td><strong>#{{ task.id }}</strong></td><td>{{ task.projectName }}<small>#{{ task.projectId }}</small></td><td>{{ task.ownerName || "-" }}</td><td>{{ task.groupName }}</td><td>{{ task.taskClass || "-" }}<small>{{ task.model || "-" }}</small></td><td><span class="task-state" :class="task.state || 'unknown'">{{ stateLabel(task.state) }}</span></td><td>{{ formatAdminDate(task.startTime) }}</td><td class="reason-cell">{{ task.reason || task.description || "-" }}</td></tr>
    </tbody></table></div><div v-if="result.total > pageSize" class="pagination" aria-label="任务分页"><t-button variant="outline" size="small" :disabled="page <= 1" @click="changePage(page - 1)">上一页</t-button><span>第 {{ page }} / {{ totalPages }} 页</span><t-button variant="outline" size="small" :disabled="page >= totalPages" @click="changePage(page + 1)">下一页</t-button></div></section>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue"; import { storeToRefs } from "pinia";
import PageHeader from "../components/PageHeader.vue"; import LoadingState from "../components/LoadingState.vue"; import EmptyState from "../components/EmptyState.vue"; import ErrorState from "../components/ErrorState.vue"; import { formatAdminDate } from "../components/adminDate"; import { useAdminSessionStore } from "../session";
import { adminErrorText, listGroups, listTasks, listUsers, type GroupDto, type TaskListResult, type UserDto } from "../api/adminApi";
const sessionStore = useAdminSessionStore(); const { session } = storeToRefs(sessionStore); const isSuperAdmin = computed(() => session.value?.role === "super_admin");
const result = ref<TaskListResult>({ page: 1, pageSize: 20, total: 0, items: [] }); const groups = ref<GroupDto[]>([]); const users = ref<UserDto[]>([]); const loading = ref(true); const refreshing = ref(false); const loadError = ref(""); const page = ref(1); const pageSize = 20; let requestSequence = 0;
const filters = reactive<{ state: string; taskClass: string; groupId: number | ""; ownerUserId: number | "" }>({ state: "", taskClass: "", groupId: "", ownerUserId: "" });
const stateOptions = [{ label: "全部状态", value: "" }, { label: "执行中", value: "running" }, { label: "已完成", value: "completed" }, { label: "失败", value: "failed" }, { label: "已取消", value: "cancelled" }];
const taskClassOptions = [{ label: "全部类型", value: "" }, { label: "文本", value: "text" }, { label: "图片", value: "image" }, { label: "视频", value: "video" }];
const groupOptions = computed(() => [{ label: "全部分组", value: "" }, ...groups.value.map((group) => ({ label: group.name, value: group.id }))]);
const userOptions = computed(() => [{ label: "全部负责人", value: "" }, ...users.value.filter((user) => !filters.groupId || user.groupId === Number(filters.groupId)).map((user) => ({ label: `${user.name} (#${user.id})`, value: user.id }))]); const totalPages = computed(() => Math.max(1, Math.ceil(result.value.total / pageSize)));
const stateLabels: Record<string, string> = { running: "执行中", completed: "已完成", succeeded: "已完成", failed: "失败", cancelled: "已取消", pending: "等待中", queued: "排队中" }; function stateLabel(state: string | null) { return state ? (stateLabels[state] || state) : "未知"; }
async function loadTargets() { const [nextUsers, nextGroups] = await Promise.all([listUsers(), isSuperAdmin.value ? listGroups() : Promise.resolve([])]); users.value = nextUsers; groups.value = nextGroups; }
async function loadTasks(silent = false) { const sequence = ++requestSequence; if (silent) refreshing.value = true; else loading.value = true; loadError.value = ""; try { result.value = await listTasks({ page: page.value, pageSize, ...(filters.state ? { state: filters.state } : {}), ...(filters.taskClass ? { taskClass: filters.taskClass } : {}), ...(isSuperAdmin.value && filters.groupId ? { groupId: Number(filters.groupId) } : {}), ...(filters.ownerUserId ? { ownerUserId: Number(filters.ownerUserId) } : {}) }); } catch (cause) { if (sequence === requestSequence) loadError.value = adminErrorText(cause, "任务加载失败"); } finally { if (sequence === requestSequence) { loading.value = false; refreshing.value = false; } } }
function applyFilters() { page.value = 1; void loadTasks(); } function changePage(nextPage: number) { page.value = nextPage; void loadTasks(); }
onMounted(async () => { try { await loadTargets(); await loadTasks(); } catch (cause) { loadError.value = adminErrorText(cause, "任务筛选项加载失败"); loading.value = false; } });
</script>

<style scoped lang="scss">
.admin-page { width: min(100%, 1320px); margin: 0 auto; }.toolbar { display: grid; grid-template-columns: repeat(4, minmax(150px, 1fr)); gap: 8px; margin-bottom: 12px; }.toolbar label { display: grid; gap: 5px; color: var(--stars-text-muted); font-size: 12px; }.data-section { border: 1px solid var(--stars-border); border-radius: 6px; background: #fff; }.section-heading { display: flex; min-height: 42px; align-items: center; justify-content: space-between; padding: 8px 12px; border-bottom: 1px solid var(--stars-border); }.section-heading h2 { margin: 0; font-size: 14px; }.section-heading span { color: var(--stars-text-muted); font-size: 11px; }.table-scroll { overflow-x: auto; } table { width: 100%; min-width: 1050px; border-collapse: collapse; font-size: 12px; } th { padding: 8px 10px; background: var(--stars-surface-muted); color: var(--stars-text-muted); font-weight: 600; text-align: left; white-space: nowrap; } td { max-width: 240px; padding: 8px 10px; border-top: 1px solid var(--stars-border); } td small { display: block; margin-top: 2px; color: var(--stars-text-muted); }.reason-cell { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.task-state { font-weight: 600; }.task-state.completed,.task-state.succeeded { color: var(--stars-completed); }.task-state.failed { color: #b42318; }.task-state.running { color: var(--stars-running); }.task-state.cancelled { color: #667085; }.pagination { display: flex; align-items: center; justify-content: flex-end; gap: 10px; padding: 10px 12px; border-top: 1px solid var(--stars-border); color: var(--stars-text-muted); font-size: 12px; }
@media (max-width: 760px) { .toolbar { grid-template-columns: 1fr; } }
</style>
